declare registration private.ai_budget_operation_sources%rowtype;x record;source_row record;root_clock record;account_row private.owned_ai_deletion_dispositions%rowtype;
 capture_at timestamptz;cause text;cause_request uuid;cause_item uuid;root_id uuid;version_id uuid;scope text;analysis uuid;n integer:=0;expected integer;locked integer;
begin
